def programme(activites):
    resultat = []
    for rang, activite in enumerate(activites, start=1):
        titre, minutes = activite
        resultat.append({
            "rang": rang,
            "titre": titre,
            "heures": minutes // 60,
            "minutes": minutes % 60,
        })
    return resultat

def bilan_groupes(premier, second):
    a = set(premier)
    b = set(second)
    return {
        "communs": sorted(a & b),
        "seulement_premier": sorted(a - b),
        "tous": sorted(a | b),
    }

def titres_assez_longs(activites, minimum):
    return [
        titre
        for titre, minutes in activites
        if minutes >= minimum
    ]

def stock_double(stock):
    return {
        code: quantite * 2
        for code, quantite in stock.items()
        if quantite > 0
    }

def heures_completes(durees):
    return [
        minutes // 60
        for minutes in durees
        if minutes >= 60
    ]

def fiches_disponibles(ateliers):
    return [
        {
            "id": atelier["id"],
            "libres": atelier["capacite"] - atelier["inscrits"],
        }
        for atelier in ateliers
        if atelier["capacite"] > atelier["inscrits"]
    ]

