def verifier_quantite(quantite):
    if type(quantite) is not int:
        raise TypeError("quantité : entier attendu")
    if quantite < 0:
        raise ValueError("quantité négative")
    return quantite


class Stock:

    def __init__(self, initial):
        self.quantite = verifier_quantite(initial)

    def ajouter(self, quantite):
        quantite = verifier_quantite(quantite)
        self.quantite += quantite

    def retirer(self, quantite):
        quantite = verifier_quantite(quantite)
        if quantite > self.quantite:
            raise ValueError("stock insuffisant")
        self.quantite -= quantite


def gerer_stock(initial, operations):
    stock = Stock(initial)
    erreurs = []
    for numero, operation in enumerate(operations, start=1):
        try:
            if operation["action"] == "ajouter":
                stock.ajouter(operation["quantite"])
            else:
                stock.retirer(operation["quantite"])
        except (TypeError, ValueError) as erreur:
            erreurs.append({"operation": numero, "message": str(erreur)})
    return {"quantite": stock.quantite, "erreurs": erreurs}

